(() => {
  'use strict';
  const D = window.MATERIALS_DATA;
  if (!D) return;
  const $ = (s,r=document) => r.querySelector(s);
  const $$ = (s,r=document) => [...r.querySelectorAll(s)];
  const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
  const STORE = 'materials.learning.v4';
  const now = () => new Date().toISOString();
  const clamp = (v,a,b) => Math.max(a,Math.min(b,v));
  const shuffle = a => [...a].sort(()=>Math.random()-.5);
  const fmt = (n,d=3) => Number.isFinite(n) ? (Math.abs(n)>=1e4 || (Math.abs(n)<1e-3 && n!==0) ? n.toExponential(d) : +n.toFixed(d)) : '—';

  const TOPICS = [
    {id:'density', label:'Density & bulk properties', lesson:'density', chapter:'bulk-v3', keywords:['density','volume','mass','kg m','cm³']},
    {id:'hooke', label:'Hooke’s law & stiffness', lesson:'hooke', chapter:'hooke-v3', keywords:['hooke','spring constant','stiff','proportional']},
    {id:'deformation', label:'Elastic, plastic & fracture', lesson:'force-extension', chapter:'elastic-plastic-v3', keywords:['elastic','plastic','fracture','brittle','ductile','permanent']},
    {id:'energy', label:'Elastic strain energy', lesson:'energy', chapter:'energy-v3', keywords:['elastic energy','strain energy','area under','½k','½f']},
    {id:'stress', label:'Stress & strain', lesson:'stress-strain', chapter:'stress-strain-v3', keywords:['stress','strain','cross-sectional','fractional extension']},
    {id:'young', label:'Young modulus', lesson:'young', chapter:'young-v3', keywords:['young modulus','young’s modulus','youngs modulus','gradient','gpa']},
    {id:'curves', label:'Stress–strain curves & design', lesson:'curves', chapter:'curves-v3', keywords:['stress–strain','stress-strain','breaking stress','tough','transport','design']},
    {id:'rp4', label:'Required Practical 4 & data', lesson:'rp4', chapter:'rp4-v3', keywords:['required practical','rp4','micrometer','uncertainty','best fit','young modulus experiment']}
  ];

  const baseState = {attempts:{}, notebook:[], examHistory:[], retrievalHistory:[], settings:{fontScale:1,contrast:false,focus:false,presentation:false,simple:false,zh:false}, teacherLesson:'density'};
  let S;
  try { S = Object.assign(structuredClone(baseState), JSON.parse(localStorage.getItem(STORE)||'{}')); } catch { S = structuredClone(baseState); }
  S.attempts ||= {}; S.notebook ||= []; S.examHistory ||= []; S.retrievalHistory ||= []; S.settings = {...baseState.settings,...(S.settings||{})};
  const save = () => localStorage.setItem(STORE,JSON.stringify(S));

  function topicFromText(text=''){
    const t=String(text).toLowerCase();
    let best=TOPICS[0],score=-1;
    for(const topic of TOPICS){const s=topic.keywords.reduce((n,k)=>n+(t.includes(k)?1:0),0);if(s>score){score=s;best=topic;}}
    return best.id;
  }
  function rec(topic,correct,total=1,kind='practice',detail=''){
    const a=S.attempts[topic] ||= {correct:0,total:0,long:0,calc:0,last:null,events:[]};
    a.correct += clamp(Number(correct)||0,0,total); a.total += total; if(kind==='long')a.long++; if(kind==='calc')a.calc++; a.last=now();
    a.events.push({at:a.last,correct,total,kind,detail}); a.events=a.events.slice(-30); save(); renderMastery(); decorateSpec();
  }
  function score(topic){const a=S.attempts[topic];if(!a?.total)return 0;const accuracy=a.correct/a.total;const evidence=Math.min(1,a.total/8);return Math.round(100*(accuracy*.82+evidence*.18));}
  function weakest(){return [...TOPICS].sort((a,b)=>score(a.id)-score(b.id));}

  function openView(name){
    $$('.view').forEach(v=>v.classList.toggle('active-view',v.id===`view-${name}`));
    $$('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));
    window.scrollTo({top:78,behavior:'smooth'});
  }
  function goTopic(topic,where='lesson'){
    const t=TOPICS.find(x=>x.id===topic)||TOPICS[0];
    if(where==='lesson'){
      openView('course'); setTimeout(()=>{const b=$$('#courseList .course-button').find(x=>x.textContent.toLowerCase().includes((D.lessons.find(l=>l.id===t.lesson)?.title||'').toLowerCase()));b?.click();},50);
    } else if(where==='textbook'){
      openView('textbook'); setTimeout(()=>{const b=$$('#textbookList .chapter-button').find(x=>x.textContent.startsWith(String((D.textbook.findIndex(c=>c.id===t.chapter)+1)))||x.textContent.toLowerCase().includes(t.label.split('&')[0].trim().toLowerCase()));b?.click();},50);
    } else if(where==='simulation'){openView('lab');}
  }

  const extraTeach = {
    density:[['Measurement routes','Regular solids: calculate volume from measured dimensions. Irregular solids: displacement can be used. In either case, the density calculation is only as reliable as the mass and volume measurements.'],['Powers of ten','For cubic conversions, the conversion factor must also be cubed. Since 1 cm = 10⁻² m, 1 cm³ = 10⁻⁶ m³.'],['Estimation strategy','Estimate dimensions to one significant figure, calculate an order-of-magnitude volume, then combine with a plausible density to test whether an answer is sensible.'],['Material choice','Low density can reduce vehicle mass, but density alone says nothing about stiffness, breaking stress or energy absorption.']],
    hooke:[['Gradient reasoning','For F on the vertical axis and extension on the horizontal axis, gradient = ΔF/Δx = k. Reversing the axes gives 1/k.'],['Sample stiffness vs material stiffness','Spring constant belongs to a particular sample. Young modulus later removes length and area effects to describe the material itself.'],['Experimental evidence','A straight line through the origin supports F ∝ ΔL. A straight line that does not pass through the origin does not show direct proportionality.'],['Limit language','The limit of proportionality is identified from graph shape; the elastic limit is identified by unloading and checking whether permanent extension remains.']],
    'force-extension':[['Loading and unloading','To test elasticity, load the sample and then remove the load. Returning to the original length is evidence of elastic behaviour.'],['Permanent set','If unloading leaves a non-zero extension, the sample has a permanent set and plastic deformation has occurred.'],['Fracture evidence','Brittle materials show little plastic extension before fracture; ductile materials can deform substantially before failure.'],['Graph caution','A curved force–extension graph alone does not prove plastic deformation. You need unloading evidence to establish permanence.']],
    energy:[['Work as graph area','For changing force, work done is the area under the force–extension graph. Only a straight Hookean line gives the simple triangular area ½FΔL.'],['Derivation','With F=kx, E=½Fx becomes E=½kx². This explains why doubling extension quadruples stored energy.'],['Conservation','Elastic energy can become kinetic and gravitational potential energy. Real systems may transfer some energy internally through damping or irreversible deformation.'],['Non-linear loading','For a curved graph, estimate area using trapezia or numerical methods rather than forcing the Hookean formula onto non-Hookean data.']],
    'stress-strain':[['Why normalise','Force depends on sample area and extension depends on original length. Stress and strain remove those size effects so different samples can be compared fairly.'],['Diameter sensitivity','Wire area uses d². A 2% uncertainty in diameter gives about 4% uncertainty in area, so diameter measurement often dominates uncertainty.'],['Units','Stress has units Pa = N m⁻². Strain is dimensionless because it is one length divided by another.'],['Graph transformation','Convert each force–extension data pair into stress–strain using the same measured area and original length before finding Young modulus.']],
    young:[['Derivation','E = stress/strain = (F/A)/(ΔL/L) = FL/(AΔL). The combined equation is therefore a consequence of the definitions, not a separate law.'],['Meaning of a large E','A large Young modulus means a large stress is required for a small strain: the material is stiff in tension.'],['Not strength','Young modulus does not give breaking stress. A stiff material can still be brittle or fail at relatively low strain.'],['Graph method','Use only the initial linear elastic region. Take a large gradient triangle on a best-fit line rather than adjacent noisy points.']],
    curves:[['Four separate properties','Initial gradient → stiffness; breaking stress → tensile strength; strain at fracture → ductility; area under curve → energy absorbed per unit volume.'],['Design trade-offs','Transport design can involve low mass, stiffness, strength, controlled deformation, energy absorption, cost, repairability and resource use.'],['Evidence-based comparison','A strong comparison names the property, quotes graph/table evidence and links it to the design requirement.'],['Ethical context','Physics informs choices but does not make the ethical decision by itself. State the physical consequences and the wider trade-off separately.']],
    rp4:[['Apparatus logic','Use a long, straight wire, measure diameter with a micrometer, measure the original length, add known masses and determine small extensions.'],['Diameter method','Measure diameter at several positions and in perpendicular orientations, correct any zero error, then use a mean diameter.'],['Data route','For each load: F=mg, stress=F/A, strain=ΔL/L. Plot stress vertically against strain horizontally; gradient gives E.'],['Quality control','Load gently, wait for oscillations to settle, avoid parallax, remain below the elastic limit, repeat measurements and use a wide elastic range.'],['Evaluation','Separate random effects (scatter/readings) from systematic effects (zero error/calibration/support movement) and propose a targeted improvement for each.']]
  };
  for(const l of D.lessons){if(l._v4)continue;l._v4=true;(extraTeach[l.id]||[]).forEach(x=>l.teach.push(x));l.activity += ' Then: (1) state the relationship you expect, (2) show one calculation with units, (3) sketch or interpret the relevant graph, and (4) write a two-sentence exam explanation using evidence.';if(l.worked?.steps&&!l.worked.steps.some(x=>String(x).includes('Check:')))l.worked.steps.push('Check: confirm SI units, sensible significant figures and a physically plausible magnitude.');}

  const deep = {
    'bulk-v3':`<section class="deep-section"><h3>Measurement, estimation and uncertainty</h3><p>For a regular block, measure each dimension independently and use the appropriate volume formula. For an irregular object, displacement gives volume directly. A percentage uncertainty in each measured dimension contributes to the uncertainty in a calculated volume, so a small object measured with a coarse ruler can give a poor density value.</p><h4>Second worked example</h4><p>A cylinder has mass 0.245 kg, diameter 25.0 mm and length 80.0 mm. Convert to metres, find <button class="equation-link" data-equation="area">A = πd²/4</button>, then V=AL and finally <button class="equation-link" data-equation="density">ρ = m/V</button>. The important skill is controlling the mm → m conversion before squaring the diameter.</p><h4>Graph skill</h4><p>For several samples of one uniform material, a graph of mass against volume should be a straight line through the origin. Its gradient is density.</p><div class="checkpoint-v4"><strong>Checkpoint:</strong> Why can two objects with different masses still have the same density?</div></section>`,
    'hooke-v3':`<section class="deep-section"><h3>From measurements to a stiffness value</h3><p>Record force and extension, plot F against ΔL and identify the straight region. If the line passes through the origin, the data support direct proportionality. The gradient of that region is <button class="equation-link" data-equation="hooke">k = F/ΔL</button>.</p><h4>Worked graph example</h4><p>If a best-fit line changes from 2.0 N at 8.0 mm to 8.0 N at 32.0 mm, ΔF=6.0 N and Δx=0.024 m, so k=250 N m⁻¹.</p><h4>Why the axes matter</h4><p>If extension is on the vertical axis instead, the gradient is Δx/ΔF=1/k. Always read the axis labels before interpreting a gradient.</p><div class="checkpoint-v4"><strong>Checkpoint:</strong> Explain why “force increases when extension increases” is weaker than saying the quantities are directly proportional.</div></section>`,
    'elastic-plastic-v3':`<section class="deep-section"><h3>Interpreting loading history</h3><p>Elasticity is a statement about reversibility. A sample may be non-linear yet still return to its original length. Plastic deformation is proven when a permanent extension remains after unloading.</p><h4>Microscopic picture</h4><p>Small elastic deformation changes interatomic separations reversibly. Larger loading can allow irreversible structural rearrangement, leaving a permanent change in shape. Treat this as a model that helps explain the macroscopic graph.</p><h4>Exam comparison</h4><p>A brittle sample can have a large Young modulus but a small fracture strain; a ductile sample can have a lower initial gradient but survive much larger strains before fracture.</p><div class="checkpoint-v4"><strong>Checkpoint:</strong> What measurement would you make after removing the load to test whether the elastic limit was exceeded?</div></section>`,
    'energy-v3':`<section class="deep-section"><h3>Energy from any force–extension graph</h3><p>Work done is the integral of force with respect to extension; graphically it is the area under F–x. For a straight line from the origin, the average force is F/2 and <button class="equation-link" data-equation="energy1">E = ½FΔL</button>. Combining with Hooke’s law gives <button class="equation-link" data-equation="energy2">E = ½k(ΔL)²</button>.</p><h4>Conservation example</h4><p>If a spring launches a mass vertically and losses are negligible, elastic energy can become kinetic energy and then gravitational potential energy. Set the initial stored elastic energy equal to the final energy store required by the question.</p><h4>Non-Hookean case</h4><p>When the line curves, split the region into trapezia or use a numerical graph area. Do not use ½Fx unless the question justifies a triangular area.</p><div class="checkpoint-v4"><strong>Checkpoint:</strong> Why does doubling extension quadruple Hookean elastic energy?</div></section>`,
    'stress-strain-v3':`<section class="deep-section"><h3>Geometry is the reason stress and strain exist</h3><p>A thicker wire carries the same force at lower stress because the force is spread over a larger area. A longer wire can extend more for the same strain because strain compares extension with original length.</p><h4>Wire calculation chain</h4><p>Diameter d → <button class="equation-link" data-equation="area">A = πd²/4</button> → <button class="equation-link" data-equation="stress">σ = F/A</button>. Original length L and extension ΔL → <button class="equation-link" data-equation="strain">ε = ΔL/L</button>.</p><h4>Uncertainty</h4><p>Because area depends on d², fractional uncertainty in area is approximately twice fractional uncertainty in d. This is why repeated micrometer readings matter in RP4.</p><div class="checkpoint-v4"><strong>Checkpoint:</strong> Two wires carry the same force. Which has the larger stress: the thinner or thicker wire, and why?</div></section>`,
    'young-v3':`<section class="deep-section"><h3>Deriving the combined Young-modulus equation</h3><p>Start with <button class="equation-link" data-equation="young">E = σ/ε</button>. Substitute <button class="equation-link" data-equation="stress">σ = F/A</button> and <button class="equation-link" data-equation="strain">ε = ΔL/L</button>. Dividing by a fraction gives E=(F/A)(L/ΔL)=FL/(AΔL).</p><h4>Rearranging for extension</h4><p><button class="equation-link" data-equation="youngExtension">ΔL = FL/(AE)</button>. This predicts: double L → double extension; double F → double extension; double diameter → four times the area → one quarter the extension.</p><h4>Graph interpretation</h4><p>On stress-y against strain-x, gradient=E. Use the linear elastic section only. A high E means stiff, while a high breaking stress means strong in tension; these are different properties.</p><div class="checkpoint-v4"><strong>Checkpoint:</strong> Why can two differently sized wires made from the same material have different spring constants but the same Young modulus?</div></section>`,
    'curves-v3':`<section class="deep-section"><h3>Reading a stress–strain graph systematically</h3><ol><li>Read the initial gradient for stiffness/Young modulus.</li><li>Find the largest stress sustained before fracture for tensile strength.</li><li>Compare strain at fracture for ductility/brittleness.</li><li>Compare total area for energy absorbed per unit volume.</li></ol><h4>Common comparison error</h4><p>Do not describe a material with the steepest initial slope as “strongest” unless it also has the greatest failure stress. Stiffness and strength answer different questions.</p><h4>Design example</h4><p>A crash-energy absorber may deliberately deform to absorb energy, whereas a precision support may prioritise a high Young modulus so that strain remains small.</p><div class="checkpoint-v4"><strong>Checkpoint:</strong> Which graph feature would you use to justify “more ductile”?</div></section>`,
    'design-v3':`<section class="deep-section"><h3>Quantitative material selection</h3><p>A good justification follows requirement → property → evidence → trade-off. Example: “The tie should stretch as little as possible, so choose the material with the larger Young modulus; however, density should also be considered if mass matters.”</p><h4>Transport and energy</h4><p>Vehicle structures can be designed to deform in selected regions so that kinetic energy is transferred into deformation work. That can reduce the rate at which passenger momentum changes, but design also considers mass, repairability, cost, resource use and safety.</p><h4>Ethical reasoning</h4><p>Separate the measured physics from value judgements. Physics can identify likely consequences of each option; the ethical choice depends on how different consequences are weighed.</p><div class="checkpoint-v4"><strong>Checkpoint:</strong> Why is “use the strongest material” not a complete engineering decision?</div></section>`,
    'rp4-v3':`<section class="deep-section"><h3>Full RP4 reasoning chain</h3><ol><li>Inspect the wire and remove kinks; set up a stable reference.</li><li>Check micrometer zero error.</li><li>Measure diameter at multiple positions and orientations; calculate a mean.</li><li>Measure original length L over the loaded section.</li><li>Add masses gently; wait for oscillations to settle; record extension.</li><li>Calculate force with <button class="equation-link" data-equation="weight">F = mg</button>.</li><li>Convert each row to stress and strain.</li><li>Plot stress against strain; use a large best-fit gradient triangle to determine E.</li><li>Unload to check that permanent extension has not developed.</li></ol><h4>Uncertainty strategy</h4><p>Quote instrument resolution where appropriate, use half-range or repeat scatter for repeated measurements, propagate diameter uncertainty into area, and discuss systematic effects such as zero error or support movement separately from random scatter.</p><h4>Evaluation sentence frame</h4><p>“The largest percentage uncertainty is likely to come from ___ because ___. I would reduce it by ___, which increases/reduces ___.”</p><div class="checkpoint-v4"><strong>Checkpoint:</strong> Why does using a longer wire improve the percentage uncertainty in extension?</div></section>`
  };
  for(const ch of D.textbook){if(!ch._v4){ch._v4=true;ch.html += deep[ch.id]||'';}}

  const EQ = {
    density:{formula:'ρ = m/V',name:'Density',meaning:'Density is mass per unit volume.',symbols:[['ρ','density','kg m⁻³'],['m','mass','kg'],['V','volume','m³']],rearr:['m = ρV','V = m/ρ'],derive:'This is the definition of density: compare the amount of mass with the volume that contains it.',worked:'0.540 kg in 6.0×10⁻⁵ m³ gives ρ=0.540/(6.0×10⁻⁵)=9.0×10³ kg m⁻³.',graph:'On mass-y against volume-x for one material, the gradient is density.',traps:['Convert cm³ to m³ using 10⁻⁶.','Density is not mass; it is a ratio.']},
    hooke:{formula:'F = kΔL',name:'Hooke’s law',meaning:'Within the proportional region, force and extension are directly proportional.',symbols:[['F','force','N'],['k','spring constant','N m⁻¹'],['ΔL','extension','m']],rearr:['k = F/ΔL','ΔL = F/k'],derive:'Direct proportionality means F/ΔL is constant; that constant is k.',worked:'4.5 N causing 18 mm = 0.018 m gives k=4.5/0.018=250 N m⁻¹.',graph:'On F-y against ΔL-x, gradient=k. Reverse the axes and gradient=1/k.',traps:['Use extension, not total length.','Hooke’s law is a proportionality statement, not just an equation.']},
    energy1:{formula:'E = ½FΔL',name:'Elastic strain energy',meaning:'For linear Hookean loading from zero, stored energy equals the triangular area under the force–extension graph.',symbols:[['E','elastic strain energy','J'],['F','final force','N'],['ΔL','extension','m']],rearr:['F = 2E/ΔL','ΔL = 2E/F'],derive:'Work=area under F–x. A straight line from 0 to F forms a triangle: ½×base×height.',worked:'F=12 N and extension=0.040 m gives E=0.5×12×0.040=0.24 J.',graph:'It is literally the area under an F–x graph only for a triangular Hookean region.',traps:['Do not use with a strongly curved loading graph.','Final force is not the average force.']},
    energy2:{formula:'E = ½k(ΔL)²',name:'Hookean elastic energy',meaning:'Elastic energy stored in a Hookean spring can be written using spring constant and extension.',symbols:[['E','energy','J'],['k','spring constant','N m⁻¹'],['ΔL','extension','m']],rearr:['k = 2E/(ΔL)²','ΔL = √(2E/k)'],derive:'Substitute F=kΔL into E=½FΔL.',worked:'k=320 N m⁻¹ and x=0.050 m gives E=0.5×320×0.050²=0.40 J.',graph:'Same triangular area under F=kx.',traps:['Doubling extension quadruples energy.','Keep extension in metres.']},
    stress:{formula:'σ = F/A',name:'Tensile stress',meaning:'Stress is tensile force per cross-sectional area.',symbols:[['σ','tensile stress','Pa'],['F','tensile force','N'],['A','cross-sectional area','m²']],rearr:['F = σA','A = F/σ'],derive:'Dividing by area removes the effect of sample thickness, allowing fairer material comparison.',worked:'50 N on area 1.96×10⁻⁷ m² gives 2.55×10⁸ Pa.',graph:'Stress is normally the vertical axis on a stress–strain graph.',traps:['Use area, not diameter.','Convert mm to m before squaring.']},
    strain:{formula:'ε = ΔL/L',name:'Tensile strain',meaning:'Strain is fractional extension: extension divided by original length.',symbols:[['ε','tensile strain','no unit'],['ΔL','extension','m'],['L','original length','m']],rearr:['ΔL = εL','L = ΔL/ε'],derive:'Dividing by original length removes the effect that longer samples naturally extend more.',worked:'2.5 mm extension of a 2.0 m wire gives ε=0.0025/2.0=1.25×10⁻³.',graph:'Strain is normally the horizontal axis on a stress–strain graph.',traps:['Strain has no unit.','Use original length, not final length.']},
    area:{formula:'A = πd²/4',name:'Circular wire area',meaning:'Cross-sectional area of a circular wire from diameter.',symbols:[['A','area','m²'],['d','diameter','m']],rearr:['d = √(4A/π)'],derive:'Radius r=d/2, so A=πr²=π(d/2)²=πd²/4.',worked:'d=0.50 mm=5.0×10⁻⁴ m gives A≈1.96×10⁻⁷ m².',graph:'Not normally graphed, but area feeds directly into stress and Young modulus.',traps:['Diameter is squared.','Percentage uncertainty in area is about twice that in diameter.']},
    young:{formula:'E = σ/ε = FL/(AΔL)',name:'Young modulus',meaning:'Young modulus is tensile stress divided by tensile strain in the proportional elastic region.',symbols:[['E','Young modulus','Pa'],['σ','stress','Pa'],['ε','strain','—'],['F','force','N'],['L','original length','m'],['A','area','m²'],['ΔL','extension','m']],rearr:['σ = Eε','ε = σ/E','ΔL = FL/(AE)','F = EAΔL/L'],derive:'E=(F/A)/(ΔL/L)=FL/(AΔL).',worked:'F=50 N, L=2.0 m, A=2.0×10⁻⁷ m², ΔL=2.5×10⁻³ m gives E=2.0×10¹¹ Pa.',graph:'Gradient of stress-y against strain-x in the initial linear region.',traps:['Young modulus measures stiffness, not breaking strength.','Use only elastic proportional data.']},
    youngExtension:{formula:'ΔL = FL/(AE)',name:'Extension of a wire',meaning:'Rearranged Young-modulus relationship for elastic extension.',symbols:[['ΔL','extension','m'],['F','force','N'],['L','original length','m'],['A','area','m²'],['E','Young modulus','Pa']],rearr:['F = EAΔL/L','L = AEΔL/F','A = FL/(EΔL)'],derive:'Rearrange E=FL/(AΔL) to make ΔL the subject.',worked:'Doubling diameter makes area four times larger, so extension becomes one quarter if F,L,E stay fixed.',graph:'For fixed A,L,E, extension is proportional to force.',traps:['Diameter affects extension through area ∝d².']},
    weight:{formula:'F = mg',name:'Force from a hanging mass',meaning:'The load force is the weight of the hanging mass.',symbols:[['F','weight / tensile load','N'],['m','mass','kg'],['g','gravitational field strength','N kg⁻¹']],rearr:['m = F/g'],derive:'Weight is the gravitational force on the mass.',worked:'2.0 kg gives F≈2.0×9.81=19.6 N.',graph:'In RP4, this converts each added mass into force.',traps:['Use total hanging mass including the mass hanger if required.']}
  };
  function equationKey(el){if(el?.dataset?.equation&&EQ[el.dataset.equation])return el.dataset.equation;const t=(el?.textContent||'').replace(/\s+/g,'');return Object.keys(EQ).find(k=>t.includes(EQ[k].formula.replace(/\s+/g,'')))||(t.includes('E=σ/ε')?'young':null);}
  function installEquationModal(){if($('#equationExplorerV4'))return;const m=document.createElement('div');m.id='equationExplorerV4';m.className='v4-modal hidden';m.innerHTML=`<div class="v4-modal-card"><button class="modal-close" id="closeEquationV4" aria-label="Close">×</button><div id="equationV4Body"></div></div>`;document.body.appendChild(m);$('#closeEquationV4').onclick=()=>m.classList.add('hidden');m.addEventListener('click',e=>{if(e.target===m)m.classList.add('hidden');});document.addEventListener('click',e=>{const btn=e.target.closest('.equation-link,.v4-equation');if(!btn)return;const k=equationKey(btn);if(!k)return;e.preventDefault();e.stopImmediatePropagation();showEquation(k);},true);}
  function showEquation(k){const x=EQ[k];if(!x)return;const m=$('#equationExplorerV4');$('#equationV4Body').innerHTML=`<span class="eyebrow">Equation explorer</span><h2>${esc(x.name)}</h2><div class="equation-hero-v4">${esc(x.formula)}</div><p>${esc(x.meaning)}</p><div class="eq-grid-v4"><section><h3>Symbols & units</h3><ul>${x.symbols.map(s=>`<li><strong>${esc(s[0])}</strong> — ${esc(s[1])} <span class="muted">(${esc(s[2])})</span></li>`).join('')}</ul></section><section><h3>Useful rearrangements</h3>${x.rearr.map(r=>`<div class="equation-chip-v4">${esc(r)}</div>`).join('')}</section></div><h3>Where it comes from</h3><p>${esc(x.derive)}</p><h3>Worked reasoning</h3><div class="worked">${esc(x.worked)}</div><h3>Graph interpretation</h3><p>${esc(x.graph)}</p><h3>Common mistakes</h3><ul>${x.traps.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="button-row"><button class="button primary" data-eq-practice="${k}">Practice this equation</button></div>`;m.classList.remove('hidden');$('[data-eq-practice]',m).onclick=()=>{m.classList.add('hidden');openView('formula');setTimeout(()=>$('#calcPracticeV4')?.scrollIntoView({behavior:'smooth'}),80);};}
  function decorateTextbookEquations(){const root=$('#textbookArticle');if(!root)return;$$('.equation-link',root).forEach(b=>b.title='Click for full equation explanation');const patterns=[['F = mg','weight'],['ΔL = FL/(AE)','youngExtension'],['k = F/ΔL','hooke'],['E = σ/ε','young']];const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const n of nodes){if(n.parentElement?.closest('button,.equation-link,.v4-equation,script,style'))continue;let text=n.nodeValue;for(const [p,k] of patterns){const i=text.indexOf(p);if(i<0)continue;const frag=document.createDocumentFragment();frag.append(text.slice(0,i));const b=document.createElement('button');b.className='v4-equation';b.dataset.equation=k;b.textContent=p;b.title='Click for full equation explanation';frag.append(b);frag.append(text.slice(i+p.length));n.replaceWith(frag);break;}}}

  function installSystemView(){if($('#view-system'))return;const nav=$('.main-nav');const specBtn=$('[data-view="spec"]',nav);const b=document.createElement('button');b.className='nav-button';b.dataset.view='system';b.textContent='Learning System';specBtn?nav.insertBefore(b,specBtn):nav.appendChild(b);b.onclick=()=>openView('system');const main=$('main.wrap.main')||$('main');const sec=document.createElement('section');sec.className='view';sec.id='view-system';sec.innerHTML=`<div class="section-head"><div><span class="eyebrow">Adaptive learning</span><h2>Materials Learning System</h2></div><p class="muted">Mastery, timed papers, spaced retrieval, engineering decisions, examiner feedback, notebook and teacher tools in one place.</p></div><div class="system-tabs-v4"><button class="button primary" data-system-tab="dashboard">Dashboard</button><button class="button" data-system-tab="exam">Exam Mode</button><button class="button" data-system-tab="retrieval">Retrieval</button><button class="button" data-system-tab="errors">Error Spotter</button><button class="button" data-system-tab="engineering">Engineering</button><button class="button" data-system-tab="notebook">Notebook</button><button class="button" data-system-tab="teacher">Teacher & Access</button></div><div id="systemPanelV4"></div>`;main.appendChild(sec);$$('.system-tabs-v4 [data-system-tab]').forEach(x=>x.onclick=()=>{$$('.system-tabs-v4 .button').forEach(q=>q.classList.remove('primary'));x.classList.add('primary');renderSystem(x.dataset.systemTab);});renderSystem('dashboard');const hero=$('.hero-actions');if(hero&&!$('[data-jump-system]',hero)){const q=document.createElement('button');q.className='button';q.dataset.jumpSystem='1';q.textContent='Open Learning System';q.onclick=()=>openView('system');hero.appendChild(q);}}
  function renderSystem(tab){const panel=$('#systemPanelV4');if(!panel)return;if(tab==='dashboard')renderDashboard(panel);if(tab==='exam')renderExam(panel);if(tab==='retrieval')renderRetrieval(panel);if(tab==='errors')renderErrors(panel);if(tab==='engineering')renderEngineering(panel);if(tab==='notebook')renderNotebook(panel);if(tab==='teacher')renderTeacher(panel);}
  function renderMastery(){if($('#masteryMapV4'))renderDashboard($('#systemPanelV4'));decorateSpec();}
  function renderDashboard(panel){const weak=weakest(),next=weak[0];const totalAttempts=Object.values(S.attempts).reduce((n,a)=>n+(a.total||0),0);panel.innerHTML=`<div class="dashboard-grid-v4"><article class="panel pad"><span class="eyebrow">Adaptive recommendation</span><h3>Next best step: ${esc(next.label)}</h3><p>Your lowest current evidence score is ${score(next.id)}%. The app will prioritise this topic in retrieval and practice.</p><div class="button-row"><button class="button primary" data-go-lesson="${next.id}">Open lesson</button><button class="button" data-go-book="${next.id}">Open textbook</button><button class="button" data-go-sim="${next.id}">Open simulation</button></div></article><article class="panel pad"><span class="eyebrow">Examiner feedback</span><h3>${totalAttempts} assessed evidence point${totalAttempts===1?'':'s'}</h3><p>${totalAttempts<6?'Complete more marked tasks to make the diagnosis more reliable.':'Your dashboard now uses multiple pieces of evidence rather than a single quiz score.'}</p><div class="mini-history-v4">${S.examHistory.slice(-3).reverse().map(e=>`<div><strong>${esc(e.mode)}</strong><span>${e.score}/${e.max}</span></div>`).join('')||'<span class="muted">No timed papers completed yet.</span>'}</div></article></div><div class="panel pad"><div class="section-head compact"><div><span class="eyebrow">Mastery map</span><h3 id="masteryMapV4">AQA Materials evidence map</h3></div><p class="muted">Scores combine accuracy and amount of evidence; grey means not yet assessed.</p></div><div class="mastery-grid-v4">${TOPICS.map(t=>{const s=score(t.id),a=S.attempts[t.id];return `<button class="mastery-card-v4" data-go-lesson="${t.id}"><span>${esc(t.label)}</span><strong>${a?.total?s+'%':'Not assessed'}</strong><div class="meter-v4"><i style="width:${s}%"></i></div><small>${a?.total||0} evidence point${a?.total===1?'':'s'}</small></button>`}).join('')}</div></div>`;$$('[data-go-lesson]',panel).forEach(b=>b.onclick=()=>goTopic(b.dataset.goLesson,'lesson'));$$('[data-go-book]',panel).forEach(b=>b.onclick=()=>goTopic(b.dataset.goBook,'textbook'));$$('[data-go-sim]',panel).forEach(b=>b.onclick=()=>goTopic(b.dataset.goSim,'simulation'));}

  const calcTemplates=[()=>({topic:'density',q:'A sample has mass 0.624 kg and volume 8.0 × 10⁻⁵ m³. Calculate its density.',answer:7800,tol:.02,unit:'kg m⁻³',working:'ρ=m/V'}),()=>{const k=200+50*Math.floor(Math.random()*5),x=(20+5*Math.floor(Math.random()*7))/1000;return {topic:'hooke',q:`A spring of constant ${k} N m⁻¹ extends by ${(x*1000).toFixed(0)} mm. Calculate the force.`,answer:k*x,tol:.02,unit:'N',working:'F=kΔL'}},()=>{const k=240,x=.05;return {topic:'energy',q:'A Hookean spring has k = 240 N m⁻¹ and is extended by 0.050 m. Calculate the elastic strain energy.',answer:.5*k*x*x,tol:.02,unit:'J',working:'E=½kx²'}},()=>({topic:'stress',q:'A wire of cross-sectional area 2.0 × 10⁻⁷ m² carries a tensile force of 48 N. Calculate the tensile stress.',answer:2.4e8,tol:.02,unit:'Pa',working:'σ=F/A'}),()=>({topic:'stress',q:'A 2.0 m wire extends by 2.4 mm. Calculate the tensile strain.',answer:.0024/2,tol:.02,unit:'',working:'ε=ΔL/L'}),()=>({topic:'young',q:'A wire 2.0 m long and area 2.0 × 10⁻⁷ m² extends 2.5 mm under 50 N. Calculate Young modulus.',answer:2e11,tol:.03,unit:'Pa',working:'E=FL/(AΔL)'}),()=>({topic:'stress',q:'A circular wire has diameter 0.50 mm. Calculate its cross-sectional area.',answer:Math.PI*(.5e-3)**2/4,tol:.03,unit:'m²',working:'A=πd²/4'}),()=>({topic:'energy',q:'A spring stores 1.8 J and launches a 0.20 kg mass horizontally with negligible losses. Calculate the launch speed.',answer:Math.sqrt(2*1.8/.2),tol:.03,unit:'m s⁻¹',working:'E=½mv²'})];
  let exam={timer:null,remaining:0,questions:[],mode:'',started:false};
  function makeExam(minutes){const mcqN=minutes===20?4:minutes===30?6:8,calcN=minutes===20?2:minutes===30?3:4,longN=minutes===45?2:1;const mcq=shuffle(D.quiz).slice(0,mcqN).map(q=>({type:'mcq',topic:topicFromText(q[1]),q:q[1],choices:q[2],answer:q[3],explain:q[4],marks:1}));const calcs=shuffle(calcTemplates).slice(0,calcN).map(f=>({...f(),type:'calc',marks:3}));const longs=shuffle(D.extended).slice(0,longN).map(q=>({type:'long',topic:topicFromText(q.q),q:q.q,marks:q.marks,points:q.points||[],rubric:q.rubric||[]}));exam={timer:null,remaining:minutes*60,questions:[...mcq,...calcs,...longs],mode:`${minutes}-minute Materials paper`,started:true};}
  function renderExam(panel){if(!exam.started){panel.innerHTML=`<div class="panel pad"><span class="eyebrow">Full exam mode</span><h3>Choose a timed Materials paper</h3><p>Each paper mixes multiple choice, calculations and extended responses. Longer versions increase both breadth and written explanation.</p><div class="exam-mode-cards-v4">${[20,30,45].map(m=>`<button class="mode-card-v4" data-exam-min="${m}"><strong>${m} minutes</strong><span>${m===20?'Quick topic check':m===30?'Standard practice':'Full Materials challenge'}</span></button>`).join('')}</div></div>`;$$('[data-exam-min]',panel).forEach(b=>b.onclick=()=>{makeExam(+b.dataset.examMin);startExamTimer();renderExam(panel);});return;}panel.innerHTML=`<div class="exam-head-v4"><div><span class="eyebrow">Timed assessment</span><h3>${esc(exam.mode)}</h3></div><strong id="examTimerV4">${clock(exam.remaining)}</strong></div><form id="examFormV4">${exam.questions.map((q,i)=>`<article class="panel pad exam-question-v4"><span class="eyebrow">Question ${i+1} · ${q.marks} mark${q.marks===1?'':'s'}</span><p><strong>${esc(q.q)}</strong></p>${q.type==='mcq'?q.choices.map((c,j)=>`<label class="exam-choice-v4"><input type="radio" name="q${i}" value="${j}"> ${esc(c)}</label>`).join(''):q.type==='calc'?`<input class="exam-input-v4" type="number" step="any" name="q${i}" placeholder="Numerical answer ${esc(q.unit||'')}"><small class="muted">Show working on paper or in your notebook. Relationship: ${esc(q.working)}</small>`:`<textarea name="q${i}" rows="7" placeholder="Write a structured ${q.marks}-mark response..."></textarea>`}</article>`).join('')}<div class="button-row"><button type="button" class="button primary" id="submitExamV4">Submit paper</button><button type="button" class="button" id="cancelExamV4">End without marking</button></div></form>`;$('#submitExamV4').onclick=()=>submitExam(panel);$('#cancelExamV4').onclick=()=>{clearInterval(exam.timer);exam.started=false;renderExam(panel);};}
  function clock(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
  function startExamTimer(){clearInterval(exam.timer);exam.timer=setInterval(()=>{exam.remaining--;const e=$('#examTimerV4');if(e)e.textContent=clock(Math.max(0,exam.remaining));if(exam.remaining<=0){clearInterval(exam.timer);const p=$('#systemPanelV4');if(p)submitExam(p);}},1000);}
  function longScore(text,q){const norm=text.toLowerCase();const groups=q.rubric?.length?q.rubric:(q.points||[]).map(p=>[p[0]]);return Math.min(q.marks,groups.filter(g=>(Array.isArray(g)?g:[g]).some(k=>norm.includes(String(k).toLowerCase()))).length);}
  function submitExam(panel){clearInterval(exam.timer);const fd=new FormData($('#examFormV4'));let got=0,max=0;const rows=[];exam.questions.forEach((q,i)=>{max+=q.marks;let mark=0,answer=fd.get(`q${i}`)||'';if(q.type==='mcq')mark=Number(answer)===q.answer?q.marks:0;if(q.type==='calc'){const v=Number(answer);mark=Number.isFinite(v)&&Math.abs(v-q.answer)<=Math.max(Math.abs(q.answer)*q.tol,1e-12)?q.marks:0;}if(q.type==='long')mark=longScore(String(answer),q);got+=mark;rec(q.topic,mark,q.marks,q.type==='long'?'long':q.type==='calc'?'calc':'practice',q.q);rows.push(`<div class="exam-review-row-v4"><span>Q${i+1} · ${esc(q.topic)}</span><strong>${mark}/${q.marks}</strong><small>${q.type==='calc'?`Answer ≈ ${fmt(q.answer)} ${esc(q.unit||'')}`:q.type==='mcq'?esc(q.explain||''):mark<q.marks?'Use the model-answer checklist in Extended Response to strengthen this topic.':'Strong coverage detected.'}</small></div>`);});S.examHistory.push({at:now(),mode:exam.mode,score:got,max});S.examHistory=S.examHistory.slice(-12);save();exam.started=false;panel.innerHTML=`<div class="panel pad"><span class="eyebrow">Paper review</span><h3>Indicative score: ${got}/${max}</h3><p>This is formative marking. Long responses can earn examiner credit in valid wording that a keyword checker may miss.</p><div class="exam-review-v4">${rows.join('')}</div><div class="button-row"><button class="button primary" id="newExamV4">Choose another paper</button><button class="button" id="examDashboardV4">View mastery dashboard</button></div></div>`;$('#newExamV4').onclick=()=>renderExam(panel);$('#examDashboardV4').onclick=()=>renderSystem('dashboard');}

  let retrieval=[];
  function buildRetrieval(){const weakIds=weakest().slice(0,4).map(t=>t.id);const pool=[];for(const l of D.lessons){const topic=topicFromText(l.title+' '+l.keywords.join(' '));for(const r of l.retrieval)pool.push({topic,q:r[0],a:r[1],priority:weakIds.includes(topic)?0:1});}retrieval=shuffle(pool.sort((a,b)=>a.priority-b.priority).slice(0,14)).slice(0,5);}
  function renderRetrieval(panel){if(!retrieval.length)buildRetrieval();panel.innerHTML=`<div class="panel pad"><div class="section-head compact"><div><span class="eyebrow">Spaced retrieval</span><h3>5-minute starter</h3></div><button class="button" id="newRetrievalV4">Generate new set</button></div><p class="muted">Weaker topics are more likely to reappear.</p><div class="retrieval-set-v4">${retrieval.map((r,i)=>`<div class="retrieval-card-v4"><strong>${i+1}. ${esc(r.q)}</strong><button class="button" data-reveal-ret="${i}">Reveal</button><div class="hidden" id="retv4-${i}"><p>${esc(r.a)}</p><div class="button-row"><button class="button primary" data-ret-grade="1" data-i="${i}">Got it</button><button class="button" data-ret-grade="0" data-i="${i}">Review</button></div></div></div>`).join('')}</div></div>`;$('#newRetrievalV4').onclick=()=>{buildRetrieval();renderRetrieval(panel)};$$('[data-reveal-ret]',panel).forEach(b=>b.onclick=()=>{$(`#retv4-${b.dataset.revealRet}`).classList.remove('hidden');b.remove();});$$('[data-ret-grade]',panel).forEach(b=>b.onclick=()=>{const r=retrieval[+b.dataset.i];rec(r.topic,+b.dataset.retGrade,1,'retrieval',r.q);b.closest('.button-row').innerHTML='<span class="muted small">Recorded.</span>';});}

  const errors=[{topic:'density',work:'1 cm³ = 10⁻² m³, so 20 cm³ = 0.20 m³.',err:'The length conversion was used without cubing it.',fix:'1 cm³ = 10⁻⁶ m³.'},{topic:'hooke',work:'A straight force–extension line that misses the origin proves Hooke’s law.',err:'Direct proportionality requires a straight line through the origin.',fix:'Check both linearity and passage through the origin.'},{topic:'deformation',work:'The graph curves, therefore the material has plastically deformed.',err:'Curvature alone does not prove permanent deformation.',fix:'Unload and check for permanent extension.'},{topic:'energy',work:'Elastic energy = FΔL for a Hookean spring.',err:'The force rises from zero, so the area is triangular.',fix:'Use E = ½FΔL.'},{topic:'stress',work:'Stress = force ÷ diameter.',err:'Stress uses cross-sectional area, not diameter.',fix:'Calculate A = πd²/4 first.'},{topic:'stress',work:'Strain = 0.002 m.',err:'Strain is a ratio and has no unit.',fix:'Use ε = ΔL/L and quote no unit.'},{topic:'young',work:'The material with the greatest Young modulus is the strongest.',err:'Young modulus measures stiffness, not breaking strength.',fix:'Use breaking stress to discuss tensile strength.'},{topic:'rp4',work:'Use two adjacent graph points to find Young modulus.',err:'Adjacent points magnify reading scatter.',fix:'Use a large triangle on a best-fit line in the linear region.'}];let errorIndex=0;
  function renderErrors(panel){const e=errors[errorIndex%errors.length];panel.innerHTML=`<div class="panel pad"><span class="eyebrow">Error spotter</span><h3>Find and repair the physics mistake</h3><div class="fake-working-v4">${esc(e.work)}</div><textarea id="errorFixV4" rows="4" placeholder="Explain the mistake and correct it..."></textarea><div class="button-row"><button class="button primary" id="checkErrorV4">Check explanation</button><button class="button" id="nextErrorV4">Next error</button></div><div id="errorFeedbackV4"></div></div>`;$('#checkErrorV4').onclick=()=>{const t=$('#errorFixV4').value.toLowerCase();const terms=(e.err+' '+e.fix).toLowerCase().split(/\W+/).filter(x=>x.length>5);const hits=terms.filter(x=>t.includes(x)).length;const ok=hits>=2;$('#errorFeedbackV4').innerHTML=`<div class="feedback ${ok?'good':'partial'}"><strong>${ok?'Good diagnosis':'Compare with the key issue'}.</strong><br>${esc(e.err)}<br><strong>Correction:</strong> ${esc(e.fix)}</div>`;rec(e.topic,ok?1:.4,1,'practice',e.work);};$('#nextErrorV4').onclick=()=>{errorIndex++;renderErrors(panel)};}

  const MAT={Steel:{rho:7850,E:200,break:720,strain:.055,energy:22},Aluminium:{rho:2700,E:69,break:310,strain:.12,energy:26},Glass:{rho:2500,E:70,break:90,strain:.0013,energy:1},Polymer:{rho:1200,E:3,break:65,strain:.12,energy:42}};
  const scenarios=[{title:'Light tension member',need:'minimise mass while limiting elastic stretch',best:'Aluminium',keys:['density','young','stiff','mass']},{title:'Rigid precision support',need:'minimise elastic strain under load',best:'Steel',keys:['young','modulus','stiff','strain']},{title:'Energy-absorbing bumper insert',need:'absorb energy through controlled deformation',best:'Polymer',keys:['energy','deformation','area','strain']},{title:'Transparent brittle panel',need:'explain why glass may fail suddenly despite useful stiffness',best:'Glass',keys:['brittle','fracture','strain','young']}];let scenarioIndex=0;
  function renderEngineering(panel){const s=scenarios[scenarioIndex%scenarios.length];panel.innerHTML=`<div class="panel pad"><span class="eyebrow">Engineering materials challenge</span><h3>${esc(s.title)}</h3><p>Requirement: <strong>${esc(s.need)}</strong>.</p><div class="property-table-v4"><div><b>Material</b><b>ρ / kg m⁻³</b><b>E / GPa</b><b>breaking stress / MPa</b><b>fracture strain</b></div>${Object.entries(MAT).map(([n,m])=>`<label><input type="radio" name="materialChoiceV4" value="${n}"><b>${n}</b><span>${m.rho}</span><span>${m.E}</span><span>${m.break}</span><span>${m.strain}</span></label>`).join('')}</div><textarea id="engineeringWhyV4" rows="5" placeholder="Justify your choice using properties and data, then state one trade-off..."></textarea><div class="button-row"><button class="button primary" id="markEngineeringV4">Evaluate choice</button><button class="button" id="nextEngineeringV4">Next scenario</button></div><div id="engineeringFeedbackV4"></div></div>`;$('#markEngineeringV4').onclick=()=>{const choice=$('input[name="materialChoiceV4"]:checked')?.value||'',text=$('#engineeringWhyV4').value.toLowerCase();const concept=s.keys.filter(k=>text.includes(k)).length;const data=/\d/.test(text);const correct=choice===s.best;const val=(correct?0.55:0)+(concept>=2?0.3:concept*.1)+(data?0.15:0);$('#engineeringFeedbackV4').innerHTML=`<div class="feedback ${val>=.75?'good':val>=.4?'partial':'bad'}"><strong>${correct?'Choice is defensible for this simplified brief.':'Reconsider the primary requirement.'}</strong><br>Reference answer: ${esc(s.best)}. Strong reasoning links the requirement to the relevant property, quotes data and acknowledges a trade-off.</div>`;rec('curves',val,1,'long',s.title);addNotebook('Engineering challenge',`${s.title}: chose ${choice}. ${$('#engineeringWhyV4').value}`);};$('#nextEngineeringV4').onclick=()=>{scenarioIndex++;renderEngineering(panel)};}

  function addNotebook(title,text){if(!String(text).trim())return;S.notebook.unshift({at:now(),title,text:String(text).trim()});S.notebook=S.notebook.slice(0,100);save();}
  function renderNotebook(panel){panel.innerHTML=`<div class="panel pad"><div class="section-head compact"><div><span class="eyebrow">Student notebook</span><h3>Saved evidence and reflections</h3></div><div class="button-row"><button class="button" id="exportNotebookV4">Export JSON</button><button class="button" id="printNotebookV4">Print</button><button class="button" id="clearNotebookV4">Clear</button></div></div><textarea id="notebookAddV4" rows="4" placeholder="Add a calculation, conclusion, graph interpretation or revision note..."></textarea><button class="button primary" id="saveNoteV4">Save note</button><div class="notebook-list-v4">${S.notebook.map(n=>`<article><small>${new Date(n.at).toLocaleString()}</small><strong>${esc(n.title)}</strong><p>${esc(n.text)}</p></article>`).join('')||'<p class="muted">Nothing saved yet. Exam results and selected activities can be added here.</p>'}</div></div>`;$('#saveNoteV4').onclick=()=>{addNotebook('Manual note',$('#notebookAddV4').value);renderNotebook(panel)};$('#exportNotebookV4').onclick=()=>download('materials-notebook.json',JSON.stringify(S.notebook,null,2),'application/json');$('#printNotebookV4').onclick=()=>window.print();$('#clearNotebookV4').onclick=()=>{if(confirm('Clear the Materials notebook?')){S.notebook=[];save();renderNotebook(panel)}};}
  function download(name,text,type='text/plain'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}

  const ZH={density:'密度',mass:'质量',volume:'体积',force:'力',extension:'伸长量',stress:'应力',strain:'应变','Young modulus':'杨氏模量',elastic:'弹性',plastic:'塑性',brittle:'脆性',ductile:'延展性',energy:'能量',uncertainty:'不确定度',gradient:'斜率',diameter:'直径'};
  function applySettings(){document.documentElement.style.fontSize=`${S.settings.fontScale}em`;document.body.classList.toggle('v4-contrast',S.settings.contrast);document.body.classList.toggle('v4-focus',S.settings.focus);document.body.classList.toggle('v4-presentation',S.settings.presentation);}
  function renderTeacher(panel){const l=D.lessons.find(x=>x.id===S.teacherLesson)||D.lessons[0];panel.innerHTML=`<div class="teacher-grid-v4"><article class="panel pad"><span class="eyebrow">Teacher mode</span><h3>Lesson focus controls</h3><label class="field"><span>Lesson</span><select id="teacherLessonV4">${D.lessons.map(x=>`<option value="${x.id}" ${x.id===l.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><div class="toggle-grid-v4"><label><input type="checkbox" id="focusModeV4" ${S.settings.focus?'checked':''}> Focus mode</label><label><input type="checkbox" id="presentationModeV4" ${S.settings.presentation?'checked':''}> Presentation mode</label></div><div class="teacher-sequence-v4"><h4>Starter / retrieval</h4><ol>${l.retrieval.map(r=>`<li>${esc(r[0])}</li>`).join('')}</ol><h4>Objectives</h4><ul>${l.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>Hinge question</h4><p>${esc(l.check[0])}</p><h4>Plenary</h4><p>${esc(l.exit)}</p></div><div class="button-row"><button class="button primary" id="openTeacherLessonV4">Open lesson</button><button class="button" onclick="window.print()">Print lesson view</button></div></article><article class="panel pad"><span class="eyebrow">Accessibility & language</span><h3>Reading controls</h3><div class="button-row"><button class="button" id="fontDownV4">A−</button><button class="button" id="fontUpV4">A+</button><button class="button" id="contrastV4">High contrast</button><button class="button" id="readViewV4">Read current view aloud</button></div><label><input type="checkbox" id="simpleV4" ${S.settings.simple?'checked':''}> Show simplified-English summary in textbook</label><label><input type="checkbox" id="zhV4" ${S.settings.zh?'checked':''}> Show Mandarin key-term support</label><div id="languageSupportV4">${S.settings.zh?`<div class="glossary-v4">${Object.entries(ZH).map(([a,b])=>`<span><b>${a}</b> — ${b}</span>`).join('')}</div>`:'<p class="muted">Mandarin support adds bilingual key terminology while keeping equations and SI units unchanged.</p>'}</div></article></div>`;$('#teacherLessonV4').onchange=e=>{S.teacherLesson=e.target.value;save();renderTeacher(panel)};$('#focusModeV4').onchange=e=>{S.settings.focus=e.target.checked;save();applySettings()};$('#presentationModeV4').onchange=e=>{S.settings.presentation=e.target.checked;save();applySettings()};$('#openTeacherLessonV4').onclick=()=>goTopic(topicFromText(l.title),'lesson');$('#fontDownV4').onclick=()=>{S.settings.fontScale=clamp(S.settings.fontScale-.08,.82,1.45);save();applySettings()};$('#fontUpV4').onclick=()=>{S.settings.fontScale=clamp(S.settings.fontScale+.08,.82,1.45);save();applySettings()};$('#contrastV4').onclick=()=>{S.settings.contrast=!S.settings.contrast;save();applySettings()};$('#readViewV4').onclick=()=>{speechSynthesis.cancel();const v=$('.view.active-view')?.innerText?.slice(0,10000)||'';speechSynthesis.speak(new SpeechSynthesisUtterance(v));};$('#simpleV4').onchange=e=>{S.settings.simple=e.target.checked;save();decorateTextbookSupport()};$('#zhV4').onchange=e=>{S.settings.zh=e.target.checked;save();renderTeacher(panel);decorateTextbookSupport()};}
  function decorateTextbookSupport(){const a=$('#textbookArticle');if(!a)return;$('#simpleSummaryV4',a)?.remove();$('#zhGlossaryTextbookV4',a)?.remove();if(S.settings.simple){const p=document.createElement('div');p.id='simpleSummaryV4';p.className='simple-summary-v4';p.innerHTML='<strong>Simplified summary:</strong> Focus on the definition, the equation, what the graph shows, and one common mistake. Use the detailed section below when you are ready for full exam wording.';a.prepend(p);}if(S.settings.zh){const g=document.createElement('div');g.id='zhGlossaryTextbookV4';g.className='glossary-v4';g.innerHTML=Object.entries(ZH).map(([x,y])=>`<span><b>${x}</b> — ${y}</span>`).join('');a.prepend(g);}}

  let calcQ=calcTemplates[0]();
  const relationQs=[{q:'You know F and ΔL for a Hookean spring. Which relationship finds k?',a:'F = kΔL',opts:['ρ = m/V','F = kΔL','σ = F/A','E = σ/ε']},{q:'You know force and wire area. Which relationship gives tensile stress?',a:'σ = F/A',opts:['σ = F/A','ε = ΔL/L','E = ½FΔL','F = mg']},{q:'You know extension and original length. Which relationship gives strain?',a:'ε = ΔL/L',opts:['A = πd²/4','ε = ΔL/L','E = FL/(AΔL)','F = kΔL']},{q:'You need extension from F, L, A and E. Which rearrangement is required?',a:'ΔL = FL/(AE)',opts:['ΔL = AE/(FL)','ΔL = FL/(AE)','ΔL = FAE/L','ΔL = E/(FLA)']}];let relationIndex=0;
  function installFormulaTools(){const view=$('#view-formula');if(!view||$('#calcPracticeV4'))return;const sec=document.createElement('section');sec.id='calcPracticeV4';sec.className='v4-tool-stack';sec.innerHTML=`<div class="panel pad"><div class="section-head compact"><div><span class="eyebrow">Unlimited calculation practice</span><h3>Calculation generator</h3></div><label>Difficulty <select id="calcDiffV4"><option>Standard</option><option>Exam</option><option>Challenge</option></select></label></div><p id="calcQuestionV4"></p><div class="button-row"><input id="calcAnswerV4" type="number" step="any" placeholder="Numerical answer"><button class="button primary" id="checkCalcV4">Check</button><button class="button" id="newCalcV4">New question</button></div><div id="calcFeedbackV4"></div></div><div class="formula-layout"><article class="panel pad"><span class="eyebrow">Equation trainer</span><h3 id="relationQuestionV4"></h3><div id="relationChoicesV4" class="choice-list"></div><div id="relationFeedbackV4"></div></article><article class="panel pad"><span class="eyebrow">Calculation whiteboard</span><h3>Show every stage</h3><p id="whiteboardQuestionV4"></p><input id="wbEquationV4" placeholder="1. Equation / rearrangement"><input id="wbConvertV4" placeholder="2. Unit conversion"><input id="wbSubV4" placeholder="3. Substitution"><input id="wbAnswerV4" placeholder="4. Final answer + unit"><button class="button primary" id="checkWhiteboardV4">Check working structure</button><div id="whiteboardFeedbackV4"></div></article></div>`;view.appendChild(sec);newCalc();renderRelation();newWhiteboard();$('#newCalcV4').onclick=newCalc;$('#checkCalcV4').onclick=checkCalc;$('#checkWhiteboardV4').onclick=checkWhiteboard;}
  function newCalc(){calcQ=shuffle(calcTemplates)[0]();const e=$('#calcQuestionV4');if(e)e.innerHTML=`<strong>${esc(calcQ.q)}</strong> <span class="muted">(${esc(calcQ.unit||'')})</span>`;if($('#calcAnswerV4'))$('#calcAnswerV4').value='';if($('#calcFeedbackV4'))$('#calcFeedbackV4').innerHTML='';}
  function checkCalc(){const v=Number($('#calcAnswerV4').value),ok=Number.isFinite(v)&&Math.abs(v-calcQ.answer)<=Math.max(Math.abs(calcQ.answer)*calcQ.tol,1e-12);$('#calcFeedbackV4').innerHTML=`<div class="feedback ${ok?'good':'partial'}"><strong>${ok?'Correct':'Check your working'}.</strong> Expected ≈ ${fmt(calcQ.answer)} ${esc(calcQ.unit||'')} using ${esc(calcQ.working)}.</div>`;rec(calcQ.topic,ok?1:0,1,'calc',calcQ.q);}
  function renderRelation(){const q=relationQs[relationIndex%relationQs.length];$('#relationQuestionV4').textContent=q.q;$('#relationChoicesV4').innerHTML=shuffle(q.opts).map(o=>`<button class="choice" data-rel="${esc(o)}">${esc(o)}</button>`).join('');$('#relationFeedbackV4').innerHTML='';$$('[data-rel]').forEach(b=>b.onclick=()=>{const ok=b.dataset.rel===q.a;$('#relationFeedbackV4').innerHTML=`<div class="feedback ${ok?'good':'partial'}">${ok?'Correct.':'Use '+esc(q.a)+'.'}</div>`;rec(topicFromText(q.q+' '+q.a),ok?1:0,1,'calc',q.q);setTimeout(()=>{relationIndex++;renderRelation()},900);});}
  let wb=calcTemplates[0]();function newWhiteboard(){wb=shuffle(calcTemplates)[0]();if($('#whiteboardQuestionV4'))$('#whiteboardQuestionV4').textContent=wb.q;}
  function checkWhiteboard(){const fields=[$('#wbEquationV4').value,$('#wbConvertV4').value,$('#wbSubV4').value,$('#wbAnswerV4').value];const complete=fields.filter(x=>x.trim().length>2).length;const eq=fields[0].replace(/\s/g,'').toLowerCase(),expected=wb.working.replace(/\s/g,'').toLowerCase();const eqOk=expected.split('=')[0].split(/[½π]/)[0]?(eq.includes(expected.split('=')[0])||eq.length>4):eq.length>4;const ok=complete===4&&eqOk;$('#whiteboardFeedbackV4').innerHTML=`<div class="feedback ${ok?'good':'partial'}"><strong>${complete}/4 stages present.</strong> ${complete<4?'Show equation, conversion, substitution and a final answer with unit.':'Now compare your numerical answer with the calculation generator or Formula Coach.'}</div>`;rec(wb.topic,ok?1:.4,1,'calc',wb.q);if(ok)newWhiteboard();}

  function installPracticalLabs(){const view=$('#view-practical');if(!view||$('#dataLabV4'))return;const box=document.createElement('section');box.id='dataLabV4';box.className='v4-tool-stack';box.innerHTML=`<div class="section-head"><div><span class="eyebrow">Paper 3 preparation</span><h2>Practical & data analysis laboratory</h2></div><p class="muted">Work with imperfect measurements, uncertainties, anomalies, gradients and converted stress–strain data.</p></div><div class="practical-grid"><article class="panel pad"><h3>RP4 advanced measurement bench</h3><p>Take repeated micrometer readings with a simulated zero error, calculate a corrected mean diameter, then collect noisy extension data while staying below the elastic limit.</p><div class="button-row"><button class="button primary" id="takeDiameterV4">Take diameter reading</button><button class="button" id="zeroCheckV4">Check zero</button><button class="button" id="resetRpAdvV4">Reset</button></div><div id="diameterReadingsV4" class="mini-history-v4"></div><label class="field"><span>Load mass</span><input type="range" id="rpAdvMassV4" min="0.5" max="8" value="1" step="0.5"><output id="rpAdvMassOutV4">1.0 kg</output></label><div class="button-row"><button class="button primary" id="takeLoadV4">Take load reading</button><button class="button" id="unloadV4">Unload / check return</button></div><div id="rpAdvResultV4"></div><div class="table-scroll"><table class="data-table"><thead><tr><th>m/kg</th><th>F/N</th><th>ΔL/mm</th></tr></thead><tbody id="rpAdvRowsV4"></tbody></table></div></article><article class="panel pad"><h3>Uncertainty & best-fit gradient</h3><button class="button" id="generateDataV4">Generate imperfect dataset</button><div class="table-scroll"><table class="data-table"><thead><tr><th>#</th><th>strain</th><th>stress/MPa</th><th>exclude?</th></tr></thead><tbody id="paper3RowsV4"></tbody></table></div><canvas id="paper3GraphV4" class="v4-canvas" height="280"></canvas><div class="control-stack"><label>Gradient start row <select id="gradStartV4"></select></label><label>Gradient end row <select id="gradEndV4"></select></label></div><button class="button primary" id="calcGradientV4">Calculate gradient</button><div id="gradientFeedbackV4"></div><div class="uncertainty-box-v4"><label>Diameter / mm <input id="uncDV4" type="number" value="0.50" step="0.01"></label><label>± / mm <input id="uncDuV4" type="number" value="0.01" step="0.001"></label><button class="button" id="uncCalcV4">Estimate area % uncertainty</button><span id="uncOutV4"></span></div></article></div><div class="panel pad"><h3>Force–extension → stress–strain converter</h3><div class="converter-grid-v4"><label>Original length / m <input id="convLV4" type="number" value="2.0" step="0.1"></label><label>Diameter / mm <input id="convDV4" type="number" value="0.50" step="0.01"></label></div><p class="muted small">Paste rows as force_N, extension_mm.</p><textarea id="convDataV4" rows="6">10,0.51\n20,1.02\n30,1.53\n40,2.04\n50,2.55</textarea><button class="button primary" id="convertDataV4">Convert data</button><div id="convOutputV4"></div></div>`;view.appendChild(box);wirePracticalLabs();}
  let rpAdv={zero:.006,diam:[],rows:[],plastic:0};let paper3=[];
  function wirePracticalLabs(){const mass=$('#rpAdvMassV4');mass.oninput=()=>$('#rpAdvMassOutV4').textContent=`${(+mass.value).toFixed(1)} kg`;$('#zeroCheckV4').onclick=()=>{$('#rpAdvResultV4').innerHTML=`<div class="feedback partial">Micrometer zero reading: ${(rpAdv.zero).toFixed(3)} mm. Correct each raw reading by subtracting this zero error.</div>`;};$('#takeDiameterV4').onclick=()=>{const raw=.500+rpAdv.zero+(Math.random()-.5)*.010;rpAdv.diam.push(raw);rpAdv.diam=rpAdv.diam.slice(-8);renderRpAdv();};$('#takeLoadV4').onclick=()=>{const m=+mass.value,F=m*9.81,d=correctedDiameter()||.5,A=Math.PI*(d*1e-3)**2/4,L=2,E=200e9,stress=F/A;let x=F*L/(A*E);if(stress>3.2e8){rpAdv.plastic=Math.max(rpAdv.plastic,(stress-3.2e8)/3.2e8*.0006);x+=rpAdv.plastic;}x+=(Math.random()-.5)*.00005;rpAdv.rows.push({m,F,x});renderRpAdv();rec('rp4',stress<3.2e8?1:.5,1,'practice','RP4 load reading');};$('#unloadV4').onclick=()=>{$('#rpAdvResultV4').innerHTML=`<div class="feedback ${rpAdv.plastic?'partial':'good'}">After unloading, permanent extension ≈ ${(rpAdv.plastic*1000).toFixed(3)} mm. ${rpAdv.plastic?'The model indicates the elastic limit was exceeded.':'No permanent extension detected within model resolution.'}</div>`;};$('#resetRpAdvV4').onclick=()=>{rpAdv={zero:(Math.random()-.5)*.012,diam:[],rows:[],plastic:0};renderRpAdv();};$('#generateDataV4').onclick=()=>{paper3=[];const E=195e9;for(let i=1;i<=8;i++){const strain=i*0.00018;let stress=E*strain/1e6*(1+(Math.random()-.5)*.035);if(i===6)stress*=1.12;paper3.push({strain,stress,exclude:false});}renderPaper3();};$('#calcGradientV4').onclick=calcGradient;$('#uncCalcV4').onclick=()=>{const d=+$('#uncDV4').value,u=+$('#uncDuV4').value;$('#uncOutV4').textContent=`Diameter uncertainty ≈ ${(u/d*100).toFixed(1)}%; area uncertainty ≈ ${(2*u/d*100).toFixed(1)}%.`;rec('rp4',1,1,'calc','diameter uncertainty');};$('#convertDataV4').onclick=convertData;renderRpAdv();$('#generateDataV4').click();}
  function correctedDiameter(){if(!rpAdv.diam.length)return 0;return rpAdv.diam.reduce((a,b)=>a+(b-rpAdv.zero),0)/rpAdv.diam.length;}
  function renderRpAdv(){$('#diameterReadingsV4').innerHTML=rpAdv.diam.map((x,i)=>`<div><span>raw ${i+1}</span><strong>${x.toFixed(3)} mm</strong></div>`).join('')+(rpAdv.diam.length?`<div><span>corrected mean</span><strong>${correctedDiameter().toFixed(3)} mm</strong></div>`:'<span class="muted">No diameter readings yet.</span>');$('#rpAdvRowsV4').innerHTML=rpAdv.rows.map(r=>`<tr><td>${r.m.toFixed(1)}</td><td>${r.F.toFixed(2)}</td><td>${(r.x*1000).toFixed(3)}</td></tr>`).join('');}
  function renderPaper3(){const body=$('#paper3RowsV4');body.innerHTML=paper3.map((r,i)=>`<tr><td>${i+1}</td><td>${r.strain.toExponential(3)}</td><td>${r.stress.toFixed(1)}</td><td><input type="checkbox" data-exclude-p3="${i}" ${r.exclude?'checked':''}></td></tr>`).join('');$$('[data-exclude-p3]').forEach(c=>c.onchange=()=>{paper3[+c.dataset.excludeP3].exclude=c.checked;drawPaper3();});const opts=paper3.map((_,i)=>`<option value="${i}">${i+1}</option>`).join('');$('#gradStartV4').innerHTML=opts;$('#gradEndV4').innerHTML=opts;$('#gradStartV4').value='0';$('#gradEndV4').value=String(Math.max(1,paper3.length-1));drawPaper3();}
  function drawPaper3(){const c=$('#paper3GraphV4');if(!c)return;const ctx=c.getContext('2d'),w=c.clientWidth||600,h=280,dpr=Math.min(devicePixelRatio||1,2);c.width=w*dpr;c.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle='#081724';ctx.fillRect(0,0,w,h);const x0=55,y0=h-42,gw=w-80,gh=h-70,maxX=Math.max(...paper3.map(r=>r.strain))*1.1,maxY=Math.max(...paper3.map(r=>r.stress))*1.1;ctx.strokeStyle='#526b80';ctx.beginPath();ctx.moveTo(x0,20);ctx.lineTo(x0,y0);ctx.lineTo(w-20,y0);ctx.stroke();for(const r of paper3){ctx.fillStyle=r.exclude?'#ff8d8d':'#6fdbb0';ctx.beginPath();ctx.arc(x0+r.strain/maxX*gw,y0-r.stress/maxY*gh,5,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#a9bdcc';ctx.font='12px system-ui';ctx.fillText('strain',w/2,h-12);ctx.save();ctx.translate(14,h/2);ctx.rotate(-Math.PI/2);ctx.fillText('stress / MPa',0,0);ctx.restore();}
  function calcGradient(){const a=paper3[+$('#gradStartV4').value],b=paper3[+$('#gradEndV4').value];if(!a||!b||a===b)return;const E=(b.stress-a.stress)*1e6/(b.strain-a.strain);const err=Math.abs(E-195e9)/195e9*100;$('#gradientFeedbackV4').innerHTML=`<div class="feedback ${err<8?'good':'partial'}">Gradient ≈ ${E.toExponential(3)} Pa (${(E/1e9).toFixed(1)} GPa). Difference from model value 195 GPa ≈ ${err.toFixed(1)}%. ${err>8?'Try excluding an anomalous point and using a wider gradient triangle.':'Good use of a wide data range.'}</div>`;rec('rp4',err<8?1:.5,1,'calc','Paper 3 gradient');}
  function convertData(){const L=+$('#convLV4').value,d=+$('#convDV4').value*1e-3,A=Math.PI*d*d/4;const rows=$('#convDataV4').value.split(/\n+/).map(x=>x.split(',').map(Number)).filter(r=>r.length>=2&&r.every(Number.isFinite));const out=rows.map(([F,mm])=>({F,mm,stress:F/A,strain:(mm*1e-3)/L}));$('#convOutputV4').innerHTML=`<div class="table-scroll"><table class="data-table"><thead><tr><th>F/N</th><th>ΔL/mm</th><th>stress/MPa</th><th>strain</th></tr></thead><tbody>${out.map(r=>`<tr><td>${r.F}</td><td>${r.mm}</td><td>${(r.stress/1e6).toFixed(1)}</td><td>${r.strain.toExponential(3)}</td></tr>`).join('')}</tbody></table></div>`;rec('stress',1,1,'calc','force-extension converter');}

  function installLabTools(){const view=$('#view-lab');if(!view||$('#graphLabV4'))return;const sec=document.createElement('section');sec.id='graphLabV4';sec.className='v4-tool-stack';sec.innerHTML=`<div class="section-head"><div><span class="eyebrow">Advanced visual analysis</span><h2>Graph Lab, microscopic model & stress–strain comparison</h2></div></div><div class="formula-layout"><article class="panel pad"><h3>Interactive force–extension graph lab</h3><p>Choose the target feature, then click where you think it is on the graph. Move the gradient triangle controls to estimate the initial stiffness.</p><div class="button-row"><select id="graphTargetV4"><option value="prop">Limit of proportionality</option><option value="elastic">Elastic limit</option><option value="fracture">Fracture</option></select><button class="button" id="resetGraphLabV4">Reset</button></div><canvas id="graphCanvasV4" class="v4-canvas" height="300"></canvas><label>Gradient point 1 <input type="range" id="grad1V4" min="10" max="40" value="20"></label><label>Gradient point 2 <input type="range" id="grad2V4" min="45" max="75" value="65"></label><div id="graphLabFeedbackV4"></div></article><article class="panel pad"><h3>Microscopic deformation viewer</h3><p class="muted">Teaching model: use it to connect reversible separation changes with permanent rearrangement.</p><label>Strain model <input type="range" id="microStrainV4" min="0" max="100" value="20"></label><label><input type="checkbox" id="microPlasticV4"> Plastic rearrangement</label><canvas id="microCanvasV4" class="v4-canvas" height="300"></canvas><div id="microTextV4"></div></article></div><div class="panel pad"><h3>Advanced stress–strain comparison</h3><div class="button-row"><label><input type="checkbox" id="ssLabelsV4" checked> Show material labels</label><label><input type="checkbox" id="ssZoomV4"> Zoom initial elastic region</label></div><canvas id="ssCompareCanvasV4" class="v4-canvas" height="340"></canvas><div class="property-table-v4"><div><b>Material</b><b>E/GPa</b><b>Breaking stress/MPa</b><b>Fracture strain</b><b>Interpretation</b></div>${Object.entries(MAT).map(([n,m])=>`<div><b>${n}</b><span>${m.E}</span><span>${m.break}</span><span>${m.strain}</span><span>${m.E>100?'stiff':'more flexible'}</span></div>`).join('')}</div></div>`;view.appendChild(sec);wireLabTools();}
  function drawForceGraph(){const c=$('#graphCanvasV4');if(!c)return;const ctx=c.getContext('2d'),w=c.clientWidth||600,h=300,dpr=Math.min(devicePixelRatio||1,2);c.width=w*dpr;c.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle='#081724';ctx.fillRect(0,0,w,h);const pts=[[0,0],[.02,4],[.04,8],[.06,12],[.075,14.5],[.09,16],[.12,17.5],[.15,16.5],[.17,0]],x0=50,y0=h-40,gw=w-75,gh=h-65,maxX=.18,maxY=20;ctx.strokeStyle='#6fdbb0';ctx.lineWidth=3;ctx.beginPath();pts.forEach((p,i)=>{const x=x0+p[0]/maxX*gw,y=y0-p[1]/maxY*gh;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.strokeStyle='#526b80';ctx.beginPath();ctx.moveTo(x0,18);ctx.lineTo(x0,y0);ctx.lineTo(w-18,y0);ctx.stroke();const a=+$('#grad1V4').value/100*.075,b=+$('#grad2V4').value/100*.075,fa=200*a,fb=200*b;ctx.strokeStyle='#ffd36f';ctx.setLineDash([5,4]);ctx.strokeRect(x0+a/maxX*gw,y0-fb/maxY*gh,(b-a)/maxX*gw,(fb-fa)/maxY*gh);ctx.setLineDash([]);const k=(fb-fa)/(b-a);$('#graphLabFeedbackV4').innerHTML=`<div class="feedback good">Gradient triangle estimate ≈ ${k.toFixed(0)} N m⁻¹.</div>`;}
  function wireLabTools(){drawForceGraph();drawMicro();drawSS();$('#grad1V4').oninput=drawForceGraph;$('#grad2V4').oninput=drawForceGraph;$('#resetGraphLabV4').onclick=drawForceGraph;$('#graphCanvasV4').onclick=e=>{const r=e.currentTarget.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*.18;const target=$('#graphTargetV4').value,tx={prop:.06,elastic:.09,fracture:.17}[target],ok=Math.abs(x-tx)<.018;$('#graphLabFeedbackV4').innerHTML=`<div class="feedback ${ok?'good':'partial'}">${ok?'Good location.':'Look again at how the curve changes or ends.'} Target x≈${tx.toFixed(2)} m in this teaching graph.</div>`;rec(target==='prop'?'hooke':target==='elastic'?'deformation':'curves',ok?1:0,1,'practice','graph identification');};$('#microStrainV4').oninput=drawMicro;$('#microPlasticV4').onchange=drawMicro;$('#ssLabelsV4').onchange=drawSS;$('#ssZoomV4').onchange=drawSS;}
  function drawMicro(){const c=$('#microCanvasV4');if(!c)return;const ctx=c.getContext('2d'),w=c.clientWidth||500,h=300,dpr=Math.min(devicePixelRatio||1,2);c.width=w*dpr;c.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle='#081724';ctx.fillRect(0,0,w,h);const s=+$('#microStrainV4').value/100,plastic=$('#microPlasticV4').checked,spacing=48+s*18;for(let row=0;row<4;row++){for(let col=0;col<7;col++){const slip=plastic&&row>=2?20:0,x=55+col*spacing+slip,y=60+row*55;ctx.strokeStyle='#43637a';if(col<6){ctx.beginPath();ctx.moveTo(x+9,y);ctx.lineTo(x+spacing-9,y);ctx.stroke();}ctx.fillStyle='#7cb6ff';ctx.beginPath();ctx.arc(x,y,9,0,Math.PI*2);ctx.fill();}}$('#microTextV4').innerHTML=`<div class="feedback ${plastic?'partial':'good'}">${plastic?'Rows have slipped relative to one another: a simple model of irreversible rearrangement and permanent deformation.':'Bond spacing increases reversibly in this elastic teaching model; remove the strain and positions return.'}</div>`;}
  function drawSS(){const c=$('#ssCompareCanvasV4');if(!c)return;const ctx=c.getContext('2d'),w=c.clientWidth||700,h=340,dpr=Math.min(devicePixelRatio||1,2);c.width=w*dpr;c.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle='#081724';ctx.fillRect(0,0,w,h);const zoom=$('#ssZoomV4').checked,maxX=zoom?.004:.13,maxY=800,x0=58,y0=h-42,gw=w-88,gh=h-70,colors=['#6fdbb0','#8cb8ff','#ff9f86','#ffd36f'];ctx.strokeStyle='#526b80';ctx.beginPath();ctx.moveTo(x0,20);ctx.lineTo(x0,y0);ctx.lineTo(w-20,y0);ctx.stroke();Object.entries(MAT).forEach(([n,m],idx)=>{ctx.strokeStyle=colors[idx];ctx.lineWidth=2.5;ctx.beginPath();let first=true;for(let e=0;e<=Math.min(m.strain,maxX);e+=maxX/120){let stress=Math.min(m.E*1000*e,m.break);if(e>m.strain*.72&&m.strain>.01)stress*=.9+.1*(1-(e-m.strain*.72)/(m.strain*.28));const x=x0+e/maxX*gw,y=y0-stress/maxY*gh;first?ctx.moveTo(x,y):ctx.lineTo(x,y);first=false;}ctx.stroke();if($('#ssLabelsV4').checked){ctx.fillStyle=colors[idx];ctx.fillText(n,w-110,35+idx*18);}});ctx.fillStyle='#a9bdcc';ctx.fillText(zoom?'strain (zoomed elastic region)':'strain',w/2,h-12);ctx.save();ctx.translate(16,h/2);ctx.rotate(-Math.PI/2);ctx.fillText('stress / MPa',0,0);ctx.restore();}

  function decorateSpec(){const cards=$$('#specGrid .spec-card');if(!cards.length)return;cards.forEach(card=>{let topic='curves';const txt=card.textContent.toLowerCase();if(txt.includes('young'))topic='young';else if(txt.includes('practical'))topic='rp4';else if(txt.includes('bulk'))topic='density';const s=score(topic);let el=$('.spec-mastery-v4',card);if(!el){el=document.createElement('div');el.className='spec-mastery-v4';card.appendChild(el);}el.innerHTML=`<span>Evidence mastery: ${s||0}%</span><div class="meter-v4"><i style="width:${s}%"></i></div>`;});}
  function installEvidenceHooks(){document.addEventListener('click',e=>{const lesson=e.target.closest('.lesson-choice');if(lesson)setTimeout(()=>{const topic=topicFromText($('#lessonPanel h2')?.textContent||'');rec(topic,lesson.classList.contains('correct')?1:0,1,'practice','lesson check');},40);const quiz=e.target.closest('[data-qchoice]');if(quiz)setTimeout(()=>{const topic=topicFromText($('#quizQuestion')?.textContent||'');rec(topic,quiz.classList.contains('correct')?1:0,1,'practice','mastery quiz');},40);const ext=e.target.closest('#markExtended');if(ext)setTimeout(()=>{const m=($('#extendedFeedback')?.textContent||'').match(/score:\s*(\d+)\/(\d+)/i);if(m)rec(topicFromText($('#extendedQuestion')?.textContent||''),+m[1],+m[2],'long','extended response');const ans=$('#extendedAnswer')?.value;if(ans)addNotebook('Extended response',$('#extendedQuestion').textContent+'\n'+ans);},80);});}
  function observeTextbook(){const root=$('#textbookArticle');if(!root)return;let timer;const obs=new MutationObserver(()=>{clearTimeout(timer);timer=setTimeout(()=>{decorateTextbookEquations();decorateTextbookSupport();},0)});obs.observe(root,{childList:true,subtree:true});decorateTextbookEquations();decorateTextbookSupport();}
  function installFloatingNotebook(){if($('#notebookQuickV4'))return;const b=document.createElement('button');b.id='notebookQuickV4';b.className='notebook-quick-v4';b.textContent='＋ Notebook';b.onclick=()=>{const text=prompt('Add a quick Materials note:');if(text){addNotebook('Quick note',text);alert('Saved to notebook.');}};document.body.appendChild(b);}
  function init(){installEquationModal();installSystemView();installFormulaTools();installPracticalLabs();installLabTools();installEvidenceHooks();observeTextbook();installFloatingNotebook();applySettings();decorateSpec();const active=$('#courseList .course-button.active');active?.click();const chapter=$('#textbookList .chapter-button.active');chapter?.click();}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,20));else setTimeout(init,20);
})();